            'prod.p-6061.desc': '含鎂矽合金之熱處理型高強度鋁板，具備極優良的切削加工性、耐蝕性與陽極氧化表現。廣泛應用於半導體設備架構、自動化機械手臂、運動器材、滑翔翼與自行車骨架及道路鐵路輸送機材。',
