            'about.caption_title': '以鋁為本 · 服務為先',
            'about.caption_sub': '全台串連庫存網絡 · 迅速精準調撥送達',
            'about.headline': '深耕台灣五十載，全方位鋁合金材料供應鏈',
            'about.subheadline': 'Since 1973 —— 北、中、南服務網絡再升級',
            'about.h_history': '【企業沿革與願景】',
            'about.history': '賀華實業股份有限公司成立於 1973 年，初期專注於進出口貿易業務。歷經近 40 年的耕耘，我們已從單純的貿易商，轉型為具備「龐大現貨庫存」與「精密裁切加工能力」的綜合材料供應商。我們致力於提供迅速、優良、高效率的專業服務，成為客戶最堅實的後盾。',
            'about.h_network': '【全台服務據點佈局】',
