            'about.philo_desc': '我们坚信，优质的材料是精密工业的基石。贺华实业始终秉持诚信原则，引进国际顶级非铁金属，透过严格的公差管控与客制化加工服务，协助客户提升产品良率与国际竞争力。',
            'about.vision_title': '全方位金属供应链整合与永续发展',
            'about.vision_intro': '展望未来，贺华实业持续投资智慧化仓储与高速 CNC 加工设备，拓展半导体腔体与航太结构专用合金库存，并积极落实下料余料分类回收与绿色节能供应链目标。',
