            'temper.T.desc': 'Applies to products heat treated to produce stable tempers. Followed by digits 1-10, most notably T4 (solution treated & naturally aged), T6 (solution treated & artificial aged/precipitation hardened), and T651 (stress-relieved by controlled stretching after solution treatment, standard for aerospace machining).',
            'bitem.1.title': 'Aluminum Materials Supply',
            'bitem.1.desc': 'Import, wholesale and distribution of pure aluminum and aluminum alloys: coils, sheets, circles, foils, wires, tubes, round bars, extrusions, painted coils, mirror plates, corrugated sheets, aerospace materials, interlocking panels, 5-bar / diamond / stucco embossed tread plates, and curtain walls.',
            'bitem.2.title': 'Stainless Steel Materials',
            'bitem.2.desc': 'Standard stock supply of AISI 304, 410, 420, 430 series industrial and precision mechanical stainless steel sheets, plates, and coils.',
            'bitem.3.title': 'Magnesium Alloys',
            'bitem.3.desc': 'Supplying high specific strength, ultra-lightweight, and vibration-damping industrial magnesium alloys for 3C electronics, aerospace, and precision sporting equipment.',
            'bitem.4.title': 'Copper & Brass Materials',
            'bitem.4.desc': 'High electrical and thermal conductivity brass, red copper, phosphor bronze, and special copper alloy coils, sheets, bars, and custom profiles.',
            'bitem.5.title': 'Steel & Insulation Engineering Materials',
            'bitem.5.desc': 'Various steel products, stainless steel coils for insulation engineering (AISI 304 0.2mm–2.0mm), strapping bands and clips, pre-painted galvanized steel coils (PVC/PVDF), and galvanized iron sheets.',
            'bitem.6.title': 'Integrated Processing Services',
            'bitem.6.desc': 'Custom extrusion tooling, CNC milling, lathe turning, powder coating, anodizing, slitting, precision sawing, embossing, punching, press brake bending, hairline brushing, kraft paper laminating, and welding.',
            'bitem.7.title': 'Technical Consulting Services',
            'bitem.7.desc': 'Quotation estimates, material hardness testing, material efficiency evaluation, collaborative design for new product development, and introduction of foreign manufacturing technologies.',
            'bitem.8.title': 'Pure Metal & Foundry Ingot Supply',
            'bitem.8.desc': 'Pure aluminum ingots (99.7%), zinc ingots (99.6%), magnesium ingots (99.99%), and foundry aluminum alloys (ADC6, ADC10, ADC12, A356, A356.2, A357, A380.2, A413) tailored to client specifications.',
            'bitem.9.title': 'Mill Certificates & Quality Inspection',
            'bitem.9.desc': 'Providing manufacturer import certificates, official Mill Test Certificates (MTR), physical/chemical parameter sheets, and domestic/international eco-compliance reports (RoHS, REACH, PFOS).',
            'ind.1': 'Electronics & Computer Information',
