            'prod.p-5052-uacj.name': 'Japan UACJ 5052 Masked Plate',
            'prod.p-5052-uacj.sub': 'Low Residual Stress · Supreme Flatness · Semiconductor Vacuum Chambers',
            'prod.p-5052-uacj.desc': 'Imported from Japan’s leading producer UACJ, featuring proprietary rolling and leveling for minimal residual stress. Warp-free after extensive milling, ensuring airtightness and ultra-flat precision.',
            'prod.p-7075.name': '7075-T651 Aerospace Ultra-Hard Plate',
            'prod.p-7075.sub': 'Ultra-High Tensile Strength · Superior Fatigue Resistance · Aerospace & Jigs',
            'prod.p-7075.desc': 'The strongest commercial aluminum alloy (Al-Zn-Mg-Cu), pre-stretched (T651) to eliminate internal stress. Engineered for defense, drones, aviation components, and precision molds.',
            'prod.p-6061.name': '6061-T6 / T651 Precision Structural Plate',
            'prod.p-6061.sub': 'Superior Machinability · Excellent Anodizing · Structural Benchmark',
            'prod.p-6061.desc': 'Heat-treatable Al-Mg-Si alloy offering optimal machinability, corrosion resistance, and consistent anodizing color. Widely applied in semiconductor frames, robotics, and automation fixtures.',
            'prod.p-5083.name': '5083-H111 / H112 Marine Aluminum Plate',
            'prod.p-5083.sub': 'High Seawater Corrosion Resistance · Low-Temp Toughness · Marine & Vessels',
            'prod.p-5083.desc': 'The highest strength non-heat-treatable alloy, resistant to seawater and low-temperature brittleness. Used extensively in shipbuilding, LNG storage, cryogenics, and armor plating.',
            'prod.p-1050.name': '1050 / 1100 High Purity Industrial Pure Plate',
            'prod.p-1050.sub': 'Purity ≥99.5% · Thermal & Electrical Conductivity · Chemical Equipment',
            'prod.p-1050.desc': 'High-purity commercial aluminum with superior ductility, electrical/thermal conductivity, and chemical resistance. Used in heat sinks, reflectors, food processing, and chemical tanks.',
            'prod.p-korea-plate.name': 'Korea Four Nine Imported Precision Plate',
            'prod.p-korea-plate.sub': 'Tolerance -0.1~+0.3mm · Flatness ≤2.0mm/m · Cost-Effective',
            'prod.p-korea-plate.desc': 'Genuine Korean Four Nine brand double-sided masked precision plate, inspected for strict thickness tolerance and supreme surface smoothness.',
            'prod.p-embossed.name': 'Mirror & 5-Bar Embossed Tread Plates',
            'prod.p-embossed.sub': 'High-Reflectivity Mirror Sheets · 5-Bar Anti-Slip Plates',
            'prod.p-embossed.desc': 'Supplying Japanese imported 5-bar checkered plates, stucco, diamond plates, and German gold/silver mirror sheets for rail cars, cleanrooms, and architectural flooring.',
            'prod.p-ext-6xxx.name': '6xxx Series Structural Extrusions',
            'prod.p-ext-6xxx.sub': '6061 / 6063 / 6082 · 7 Standard Profiles · Bars & Tubes',
            'prod.p-ext-6xxx.desc': 'Massive stock of 6061/6063 round bars, flat bars, square bars, round tubes, and square hollow sections with zero tooling fees.',
            'prod.p-ext-2xxx-7xxx.name': '2xxx / 5xxx / 7xxx Aerospace & Marine Extrusions',
            'prod.p-ext-2xxx-7xxx.sub': '2011/2024 High-Speed Free Cutting · 5083 Marine · 7075 Bars',
            'prod.p-ext-2xxx-7xxx.desc': 'Supplying 2011/2024 free-cutting aerospace bars, 5083 marine structural shapes, and 7075 ultra-hard extrusion billets.',
            'prod.p-custom-mold.name': 'Custom Extrusion Tooling & Castings',
            'prod.p-custom-mold.sub': '1xxx~7xxx Custom Dies · Precision Forging & Casting Solutions',
            'prod.p-custom-mold.desc': 'End-to-end tooling development from 3D CAD review, die trial runs, precision CNC machining to anodized surface finishing.',
            'prod.p-stainless-copper.name': 'Stainless Steel, Copper, Brass & Metal Ingots',
            'prod.p-stainless-copper.sub': 'AISI 304/410/430 · Copper Tubes · 99.7% Pure Al & ADC12 Ingots',
            'prod.p-stainless-copper.desc': 'Complete one-stop metal supplier: AISI 304 stainless sheets, 99.9% copper pipes, 65/35 brass rods, and pure aluminum/ADC12 casting ingots.',
            'cap.cnc-milling.name': 'CNC Milling Machining',
            'cap.cnc-milling.desc': 'Equipped with high-rigidity vertical CNC centers specializing in 6xxx and 7xxx alloys for semiconductor chambers and precision heatsinks.',
            'cap.cnc-lathe.name': 'Precision CNC Lathe Turning',
            'cap.cnc-lathe.desc': 'Utilizing extensive bar stock, multi-axis mill-turn centers execute turning, boring, threading, and eccentric milling with high concentricity.',
            'cap.stamping.name': 'Stamping & Sheet Metal Fabrication',
            'cap.stamping.desc': 'High-speed continuous stamping, blanking, deep drawing, and bending optimized for 1050/5052 aluminum ductility.',
            'cap.five-axis.name': 'Aerospace 5-Axis Simultaneous Machining',
            'cap.five-axis.desc': 'Simultaneous 5-axis machining centers eliminate fixture repositioning errors on complex 3D aerodynamic surfaces and angled bores.',
            'cap.gantry-milling.name': 'Large Gantry Milling Machining',
            'cap.gantry-milling.desc': 'Integrated service from heavy plate sawing to large-format surface fly-cutting and boring, avoiding cross-plant transport risks.',
            'cap.polishing.name': 'Polishing & Hairline Surface Finishing',
            'cap.polishing.desc': 'Professional surface grinding, hairline brushing, and mechanical mirror polishing to enhance aesthetic value.',
            'cap.anodizing.name': 'Anodizing & Anti-Corrosion Surface Engineering',
            'cap.anodizing.desc': 'Electrochemical surface engineering offering clear, matte black, color dyeing, and wear-resistant Hard Anodizing.',
            'case.case-semiconductor.title': 'Semiconductor Vacuum Chambers & Etching Machine Components',
            'case.case-semiconductor.client': 'Global Semiconductor / Display Equipment Manufacturer',
            'case.case-semiconductor.challenge': 'Severe requirements for flatness and dimensional stability on large aluminum bases. Traditional plates warped after extensive CNC pocketing due to residual stress.',
            'case.case-semiconductor.solution': 'Supplied genuine Japanese UACJ 5052/6061 low-stress plates with controlled rolling, combined with optimized high-speed milling and stress relief techniques.',
            'case.case-semiconductor.result': 'Successfully maintained flatness within tight tolerances, drastically reducing assembly rework and winning long-term designated supplier status.',
            'case.case-aerospace.title': 'Aerospace Structural Components & High-Strength Jigs',
            'case.case-aerospace.client': 'Civil Aviation / UAV Drone / High-Speed Machinery Maker',
            'case.case-aerospace.challenge': 'Parts required extreme lightweighting and high fatigue resistance with complex 3D hollow aerodynamic profiles under strict ISO geometric tolerances.',
            'case.case-aerospace.solution': 'Supplied certified 7075-T651 aerospace alloy with Mill Test Certificates, precision machined in one clamping using simultaneous 5-axis centers.',
            'case.case-aerospace.result': 'Passed ultrasonic non-destructive testing and 3D CMM inspection, achieving significant weight reduction and showcasing our 7xxx expertise.',
            'case.case-robotics.title': 'Automated Robotic Arm Articulations & Precision Slides',
            'case.case-robotics.client': 'Industrial Robotics & Automation Systems Manufacturer',
            'case.case-robotics.challenge': 'Batch production of precision robotic arm joints requiring tight CNC tolerances, flawless aesthetic anodizing, and very tight delivery schedules.',
            'case.case-robotics.solution': 'Leveraged our integrated supply chain to select streak-free aluminum, managing precision sawing, CNC milling, sandblasting, and anodizing end-to-end.',
            'case.case-robotics.result': 'Eliminated multi-vendor coordination overhead, drastically shortened lead times, and delivered hundreds of premium components on schedule.',

