            'about.tag': 'About Harvard Enterprises · Since 1973',
            'about.title': 'About Harvard Enterprises · Four Decades in Taiwan',
            'about.desc': 'Since 1973 —— Upgraded North-Central-South service hubs —— Transitioning from global metal trading into a full-service aluminum supply chain with vast stock inventory and precision CNC machining.',
            'about.tab_all': 'All Overview',
            'about.tab_overview': 'Company History',
