            // AI Assistant Widget
            'ai.launcher': 'AI Assistant',
            'ai.launcher_sub': 'Inventory & Cutting Optimizer',
            'ai.header_title': 'HARVARD AI Engineering Assistant',
            'ai.online_status': 'Live Connected (3,071 Stock & Mold SKUs)',
            'ai.tab_chat': '💬 Specs & Alloy Q&A',
            'ai.tab_cpsat': '🧮 Cutting Stock Optimizer',
            'ai.placeholder': 'Ask stock specs, cutting plan, or alloy advice...',
            'ai.send': 'Send',
            'ai.chip1': '📦 6061 Rod 50mm',
            'ai.chip2': '🔬 High-Strength & Anodizing',
            'ai.chip3': '🧮 Cutting Demo',
            'ai.chip4': '📍 Hubs & MTR Cert',
            'ai.greeting_text': 'Hello! I am the <strong>HARVARD AI Engineering Assistant</strong>, connected in real-time to our database of 3,071 stock items and mold specs.<br><br>Feel free to ask me:<br>• <strong>Stock & Mold Specs</strong>: "6061 Round Bar 50mm", "7075 Aluminum Plate 20mm"<br>• <strong>Smart Cutting Stock</strong>: "Raw stock 3000mm cut 800*3, 550*4, 420*5"<br>• <strong>Alloy Engineering</strong>: "Recommend aluminum for hard anodizing & high strength"<br><button type="button" class="ai-bubble-audio-btn" onclick="readAloudText(\'Hello! I am the HARVARD AI Engineering Assistant. You can inquire about our stock inventory, alloy recommendations, or run 1D cutting stock optimization using AI.\', this)">🔊 Audio Introduction</button>',
            'char.lightweight.name': 'Ultra-Lightweight',
            'char.lightweight.badge': 'Density 2.7 g/cm³',
            'char.lightweight.desc': 'Specific gravity of ~2.7 is only 35% of steel (7.85) or 30% of copper (8.96). Drastically reduces structural tare weights in transit, aerospace and high-speed robotics, curbing inertia and drive energy.',
            'char.corrosion.name': 'Superior Corrosion Resistance',
            'char.corrosion.badge': 'Natural Passivation Al₂O₃',
            'char.corrosion.desc': 'Instantly forms a microscopic, self-healing aluminum oxide (Al₂O₃) barrier upon exposure to air. Anodizing further seals surfaces against aggressive marine salt spray and atmospheric acid exposure.',
            'char.machinability.name': 'High-Speed Machinability',
            'char.machinability.badge': 'Saves up to 70% Machining Time',
            'char.machinability.desc': 'Delivers exceptional cutting feeds and chip clearance with minimal spindle tool wear. Compared to steel, it reduces CNC milling cycle times and tool replacement costs by 50% to 70%.',
            'char.strength.name': 'High Strength-to-Weight Ratio',
            'char.strength.badge': 'Yields up to 600 MPa',
            'char.strength.desc': 'Alloyed with Cu, Mg, Zn, and Si and fortified via solution heat treatment and artificial aging (e.g., 7075-T651), yielding structural-steel-level tensile capacity with unmatched specific rigidity.',
            'char.surface_finish.name': 'Versatile Surface Treatments',
            'char.surface_finish.badge': 'Hard Anodizing / Bead Blast / Plating',
            'char.surface_finish.desc': 'Exceptional receptivity to hard anodizing (MIL-A-8625), micro-arc oxidation, chromate-free conversion, laser etching, and mirror polishing, providing durable wear resistance and sleek industrial aesthetics.',
            'char.thermal_conductivity.name': 'High Thermal Conductivity',
            'char.thermal_conductivity.badge': '~130–230 W/m·K',
            'char.thermal_conductivity.desc': 'Thermal conductivity is triple that of low-carbon steel, serving as the essential benchmark material for semiconductor wafer vacuum chucks, EV battery cooling plates, and heat sinks.',
            'char.electrical_conductivity.name': 'Efficient Electrical Conductivity',
            'char.electrical_conductivity.badge': '~62% IACS of Copper',
            'char.electrical_conductivity.desc': 'By weight, aluminum provides twice the electrical conductivity of copper at a substantially lower raw material cost, making it ideal for power grid busbars, switchgear, and transformers.',
            'char.formability.name': 'Superb Formability & Ductility',
            'char.formability.badge': 'O / H Multipurpose Tempers',
            'char.formability.desc': 'Outstanding plasticity in annealed condition (O-temper) allows severe deep drawing, precision stamping, bending, hydroforming, and roll-bending for aerodynamic panels and precision enclosures.',
            'char.weldability.name': 'Excellent Weldability',
            'char.weldability.badge': 'TIG / MIG / Friction Stir (FSW)',
            'char.weldability.desc': 'Pure aluminum (1xxx) and Al-Mg alloys (5052, 5083) offer premier TIG/MIG and Friction Stir Welding (FSW) performance with zero hot-crack tendencies, widely used in pressure tanks and ship hulls.',
            'char.no_low_temp_brittle.name': 'Cryogenic Toughness (No Low-Temp Brittleness)',
            'char.no_low_temp_brittle.badge': 'Toughness Increases at Subzero',
            'char.no_low_temp_brittle.desc': 'Free from ductile-to-brittle transition phenomena typical of carbon steels. Tensile and impact toughness increase at liquid nitrogen temperatures, making it the premier choice for LNG storage vessels.',
            'char.non_magnetic.name': 'Completely Non-Magnetic',
            'char.non_magnetic.badge': 'Zero Magnetic Interference',
            'char.non_magnetic.desc': 'Completely devoid of magnetic hysteresis, essential for medical MRI scanners, radar equipment, aerospace avionics housings, and high-sensitivity semiconductor EMI shielding enclosures.',
            'char.reflectivity.name': 'High Optical & Thermal Reflectivity',
            'char.reflectivity.badge': 'Reflectivity >85%',
            'char.reflectivity.desc': 'Bright rolled aluminum surfaces reflect over 85% of visible light and radiant thermal radiation, widely employed in solar collectors, architectural insulation cladding, and optical reflectors.',
            'char.non_toxic.name': 'Non-Toxic & Hygienic Safety',
            'char.non_toxic.badge': 'Food & Pharma Grade Certified',
            'char.non_toxic.desc': 'Completely odorless and non-toxic. Its inert surface layer releases no harmful elements, making it universally certified for food and beverage packaging, sterile pharma containers, and cookware.',
            'char.recyclability.name': 'Sustainable Circular Recyclability',
            'char.recyclability.badge': 'Remelting Uses Only 5% Energy',
            'char.recyclability.desc': 'Recycling recovery rate exceeds 95% with remelting requiring just 5% of primary electrolysis smelting energy, drastically lowering carbon footprints in alignment with global ESG initiatives.',
            'char.cryo_stability.name': 'Micro-Level Dimensional Stability',
            'char.cryo_stability.badge': 'Ultra-Flat Low Residual Stress',
            'char.cryo_stability.desc': 'Directly imports pre-stretched (T651) and precision cast ultra-flat plates from South Korea and Japan, eliminating internal stress to guarantee micron flatness without distortion during intensive CNC pocketing.',
            'series.1000.name': '1000 Series',
