            'temper.F.name': '製造のままの状態 (As Fabricated)',
            'temper.F.desc': '成形加工工程において加工硬化や熱処理に特別な管理を行わない製品に適用。機械的性質の保証値は定めない。',
            'temper.O.name': '完全焼なまし状態 (Annealed)',
            'temper.O.desc': '完全焼鈍により最低強度と最大延性を得た状態で、深絞り成形や曲げ加工に最適。',
            'temper.H.name': '加工硬化状態 (Strain-Hardened)',
            'temper.H.desc': '冷間加工により強度を高めた製品。H に続く数字は基本処理記号（H1 加工硬化のみ、H2 部分焼鈍、H3 安定化処理）と硬化度（2=1/4硬、4=1/2硬、8=フル硬）を示す。',
            'temper.W.name': '溶体化処理状態 (Solution Heat-Treated)',
            'temper.W.desc': '溶体化処理後、室温で自然時効硬化が進行する過渡的不安定状態。時効期間（例：W 1/2時間）の明記が必要。',
            'temper.T.name': '熱処理により安定した状態 (T)',
            'temper.T.desc': '熱処理によって安定した組織と特性を得た状態。代表例として T4（溶体化後自然時効）、T6（人工時効硬化）、T651（残留応力制御引張加工後人工時効、航空宇宙部品に必須）。',
            'bitem.1.title': 'アルミ素材供給',
            'bitem.1.desc': '純アルミおよび各種アルミ合金の輸入・卸売・加工販売。コイル、板材、丸板、アルミ箔、線材、パイプ、丸棒、押出型材、カラーアルミ、鏡面アルミ、波板、航空用材、5本筋・ダイヤ・人字縞板、カーテンウォール材など、世界各国の特殊合金に対応。',
            'bitem.2.title': 'ステンレス鋼材',
            'bitem.2.desc': 'AISI 304、410、420、430などの産業用・精密機構用ステンレス板材およびコイルを常備在庫し、迅速に供給。',
            'bitem.3.title': 'マグネシウム合金',
            'bitem.3.desc': '高比強度・超軽量・高減衰能を備えた工業用マグネシウム合金を供給。3Cエレクトロニクス、航空宇宙、精密スポーツ機器のニーズに対応。',
            'bitem.4.title': '伸銅品・銅合金',
            'bitem.4.desc': '高導電・高熱伝導性を誇る黄銅、純銅（赤銅）、りん青銅、特殊銅合金のコイル、板材、棒材、異形材を供給。',
            'bitem.5.title': '鋼材＆保温工事用資材',
            'bitem.5.desc': '各種鋼材、保温工事用ステンレス薄板（AISI 304 0.2mm〜2.0mm）、ステンレスバンド・留め具、カラー亜鉛めっき鋼板（PVC/PVDF）、トタン板を完備。',
            'bitem.6.title': '加工受託・一貫統合サービス',
            'bitem.6.desc': '特注金型開発、フライス加工、旋盤加工、焼付塗装、アルマイト処理、スリット、精密切断、エンボス、打抜き、曲げ、ヘアライン、ラミネート、溶接までワンストップ対応。',
            'bitem.7.title': '営業技術・コンサルティング',
            'bitem.7.desc': '材料見積り積算、硬さ測定、歩留まり改善提案、新製品の共同設計・開発支援、海外先端材料技術の導入・技術相談に対応。',
            'bitem.8.title': '純金属地金＆鋳造用インゴット',
            'bitem.8.desc': '純アルミ地金（99.7%）、亜鉛地金（99.6%）、マグネシウム地金（99.99%）、アルミダイカスト用合金（ADC6、ADC10、ADC12、A356、A357等）を安定供給。',
            'bitem.9.title': 'ミルシート＆国際検査証明',
            'bitem.9.desc': '原産地証明書、メーカー発行ミルシート（検査証明書 MTR）、物性データシート、各種環境規制分析データ（RoHS、REACH、PFOS等）を完備。',
            'ind.1': 'エレクトロニクス＆IT情報機器',
            'ind.2': '半導体・3Cハイテク産業',
            'ind.3': '医療用機器・ヘルスケア金属',
