            'about.history': '賀華実業股份有限公司は1973年に設立され、非鉄金属の国際貿易から始まりました。約40年にわたる信頼と実績を積み重ね、現在では「豊富な常備在庫」と「高度精密切断加工」を併せ持つ総合アルミニウム材料サプライヤーへと発展。半導体や航空宇宙分野のお客様に迅速で高品質な製品をお届けしています。',
