            'about.philo_desc': '高品質な材料こそが精密工業の礎であると確信しています。賀華実業は誠実さを社訓とし、世界最高水準の非鉄金属を調達。厳密な寸法公差管理とカスタマイズ加工により、お客様の歩留まり向上と競争力強化に貢献します。',
