            'char.corrosion.desc': '大気中で瞬時に緻密な酸化アルミニウム保護被膜を自己形成。アルマイト処理（陽極酸化）により耐酸・耐塩水性がさらに向上し、海洋環境に最適です。',
            'char.machinability.name': '高能率な切削加工性',
            'char.machinability.badge': '加工時間を最大70%削減',
            'char.machinability.desc': '優れた高速フライス・旋削加工性を誇り、切りくず排出が良好で工具摩耗が極小。鋼材に比べて切削時間を約50%〜70%大幅に短縮できます。',
            'char.strength.name': '高い比強度・剛性',
            'char.strength.badge': '最大 600 MPa 級',
            'char.strength.desc': 'Cu、Mg、Zn、Si 等の合金化と溶体化熱処理・人工時効硬化（例：7075-T651）により、構造用鋼に匹敵する強度と極めて高い比剛性を発揮します。',
            'char.surface_finish.name': '多様な表面処理性',
            'char.surface_finish.badge': '硬質アルマイト / ブラスト / メッキ',
            'char.surface_finish.desc': '硬質アルマイト（MIL規格）、マイクロアーク酸化、三価クロメート、レーザー彫刻、鏡面研磨に対応し、高品位な外観と耐摩耗性を両立します。',
            'char.thermal_conductivity.name': '優れた熱伝導性',
            'char.thermal_conductivity.badge': '約 130〜230 W/m·K',
            'char.thermal_conductivity.desc': '普通鋼の約3倍の熱伝導率を誇り、半導体ウェハー均熱板、電子ヒートシンク、EVバッテリー冷却プレート、熱交換器で不可欠な素材です。',
            'char.electrical_conductivity.name': '高効率な導電性',
            'char.electrical_conductivity.badge': '銅の約 62% IACS',
            'char.electrical_conductivity.desc': '同質量比較で純銅の約2倍の導電性能を発揮し、銅材よりも圧倒的に軽量・低コスト。配電盤ブスバーやトランス巻線に幅広く採用されています。',
            'char.formability.name': '優れた成形性・延展性',
            'char.formability.badge': 'O材 / H材 多彩な質別',
            'char.formability.desc': '焼なまし（O材）状態で優れた塑性加工性を示し、深絞り、プレス、曲げ、ロール成形に対応。各種複雑な板金筐体やリフレクターに最適です。',
            'char.weldability.name': '良好な溶接性',
            'char.weldability.badge': 'TIG / MIG / 摩擦攪拌接合 (FSW)',
            'char.weldability.desc': '1000系純アルミや5000系アルミマグネシウム合金はTIG/MIG溶接および摩擦攪拌接合（FSW）性に優れ、圧力容器や車体・船舶構造に活躍します。',
            'char.no_low_temp_brittle.name': '極低温脆化がない',
            'char.no_low_temp_brittle.badge': '極低温下で靭性が向上',
            'char.no_low_temp_brittle.desc': '炭素鋼のような低温脆性遷移を示さず、液体窒素温度域でも引張強度と衝撃靭性が向上するため、LNGタンクや極地機器の必須材料です。',
            'char.non_magnetic.name': '完全非磁性',
            'char.non_magnetic.badge': '磁気干渉ゼロ',
            'char.non_magnetic.desc': '強磁性を示さないため、医療用MRIチャンバー、レーダー航行装置、高感度電子計測器、半導体電磁シールド環境に最適です。',
            'char.reflectivity.name': '高い光・熱反射率',
            'char.reflectivity.badge': '反射率 85% 以上',
            'char.reflectivity.desc': '高純度アルミ表面は可視光や赤外熱線を85%以上反射し、太陽光集熱板、建築断熱材、高効率照明反射板、光学機器に多用されます。',
            'char.non_toxic.name': '無毒・衛生安全性',
            'char.non_toxic.badge': '食品・医療グレード適合',
            'char.non_toxic.desc': '無毒・無臭で有害物質の溶出がなく、食品・飲料包装、無菌医薬品容器、日用調理器具に世界中で安全に採用されています。',
            'char.recyclability.name': '高度なリサイクル循環性',
            'char.recyclability.badge': '再生エネルギーは新塊のわずか 5%',
            'char.recyclability.desc': 'リサイクル回収率は95%以上。再溶解に必要なエネルギーは一次製錬のわずか5%で、カーボンフットプリント低減とESG持続可能製造に直結します。',
            'char.cryo_stability.name': '高精度な応力安定性',
            'char.cryo_stability.badge': '極超平・低残留応力プレート',
            'char.cryo_stability.desc': 'プリストレッチ（T651）および精密フライス仕上げ超フラットプレートを直輸入。深彫り切削加工後も反りや歪みがなく、ミクロン公差を維持します。',
