            'series.1000.heat': '非熱処理型（加工硬化）',
            'series.1000.features': '優れた延展性、導電・熱伝導性、耐食性を誇り溶接性も良好。強度は低めですが冷間加工（H14/H18）で硬度を高められます。',
            'series.1000.apps': '食品用アルミ箔、電解コンデンサケース、照明反射板、放熱フィン、保温外装材、ブスバー。',
