            'about.history': '하버드실업 주식회사는 1986년 설립 이래 비철금속 국제 무역을 시작으로 성장해 왔습니다. 지난 40여 년간의 기술 축적을 통해 단순 무역상을 넘어 방대한 상시 재고와 초정밀 CNC 절단 가공 기술을 갖춘 종합 알루미늄 전문 기업으로 도약했습니다.',
