            'char.corrosion.desc': '대기 노출 시 자가 치유형 산화알루미늄 보호피막을 형성하여 추가 산화를 차단합니다. 아노다이징 피막 처리 시 해수 염분과 산성 환경에 극강의 내식성을 보장합니다.',
