            'char.weldability.desc': '1000계 순알루미늄 및 5000계 Al-Mg 합금은 TIG/MIG 용접과 마찰교반용접(FSW) 특성이 뛰어나 크랙 없이 견고한 압력용기 및 선박 구조물을 제작합니다.',
